step3_testbench.spice:
* Bandpass Filter Testbench

* Parameterized passive values to approximate 2.14 GHz resonance
.param L_val=2n
.param C_val=1p
.param R_val=50

* Input Source
V1 N0_in GND dc 0 ac 1
Rin N0_in N0 50

* DUT: Passive Filter Network
L1 N0 N1 {L_val}
L2 N4 N5 {L_val}
L3 N3 N6 {L_val}
R1 N3 GND {R_val}
C1 N2 GND {C_val}
C2 N5 GND {C_val}
C3 N0 GND {C_val}
C4 N3 GND {C_val}
C5 N5 N6 {C_val}
C6 N1 N2 {C_val}
R2 N2 GND {R_val}
C7 N0 N4 {C_val}

* Load
Rload N5 GND 50

.ac dec 100 100Meg 10Gig

.control
run

* Calculate Gain in dB
let gain_db = vdb(N5)

* Measure peak gain (Insertion Loss) and Center Frequency
meas ac max_gain max gain_db
meas ac gain_at_fc find gain_db at=2.14G

* Print results
print max_gain gain_at_fc

.endc
.end

